BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY, project TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, requirements TEXT NOT NULL, role TEXT NOT NULL, cadence TEXT NOT NULL, timezone TEXT NOT NULL, local_time TEXT NOT NULL, weekday INTEGER NOT NULL, next_run INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'active', created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schedule_runs(schedule TEXT NOT NULL REFERENCES schedules(id), occurrence INTEGER NOT NULL, task TEXT NOT NULL UNIQUE REFERENCES tasks(id), PRIMARY KEY(schedule,occurrence));
CREATE TABLE IF NOT EXISTS task_dates(task TEXT PRIMARY KEY REFERENCES tasks(id), due INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS intake_links(task TEXT PRIMARY KEY REFERENCES tasks(id), project TEXT NOT NULL REFERENCES projects(id), request TEXT NOT NULL, context TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS autonomy(project TEXT PRIMARY KEY REFERENCES projects(id), enabled INTEGER NOT NULL DEFAULT 0, progress_timeout INTEGER NOT NULL DEFAULT 900, status TEXT NOT NULL DEFAULT 'disabled', updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS review_jobs(task TEXT PRIMARY KEY REFERENCES tasks(id), artifact TEXT NOT NULL UNIQUE REFERENCES artifacts(id));
CREATE TABLE IF NOT EXISTS stop_evidence(attempt TEXT PRIMARY KEY REFERENCES attempts(id), runtime TEXT NOT NULL, generation TEXT NOT NULL, observed INTEGER NOT NULL, evidence TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_dispatch(message TEXT PRIMARY KEY REFERENCES messages(id), operation TEXT NOT NULL REFERENCES operations(id));
CREATE TABLE IF NOT EXISTS backup_runs(id TEXT PRIMARY KEY, destination TEXT NOT NULL, state TEXT NOT NULL, detail TEXT NOT NULL, created INTEGER NOT NULL);
INSERT OR IGNORE INTO settings VALUES('timezone','Europe/London'),('backup_interval','86400'),('backup_last','0');
UPDATE settings SET value='2' WHERE key='schema';
COMMIT;
